package local.purelight;
import java.util.*;import java.nio.file.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.Identifier;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.level.GameType;import net.minecraft.world.item.*;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.spell_engine.internals.*;import net.spell_engine.internals.casting.*;import net.spell_engine.internals.container.*;
@Mod("phase_two_probe") public class PurelightProbe {
 List<String> lines=new ArrayList<>();int failed;ServerLevel w;
 public PurelightProbe(){NeoForge.EVENT_BUS.addListener(this::start);}
 void check(boolean b,String s){lines.add((b?"PASS ":"FAIL ")+s);if(!b)failed++;}
 void start(ServerStartedEvent event){w=event.getServer().overworld();((net.spell_engine.utils.WorldScheduler)w).schedule(30,()->run(event));}
 void run(ServerStartedEvent event){try{
  var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(w);p.connection.markClientLoaded();p.setGameMode(GameType.SURVIVAL);p.setInvulnerable(false);p.getAbilities().invulnerable=false;p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(1);p.getPersistentData().remove("final_purelight_cooldown_until");FinalPurelight.stop(p);
  var h=PaladinRevamp.spell(p,"skill_tree_rpgs:paladin_tier_3_passive_2");var owner=(SpellContainerSource.Owner)p;var old=owner.getSpellContainers();owner.setSpellContainers(new SpellContainerSource.Result(old.activeContainer(),List.of(),List.of(h),List.of(),List.of(new SpellContainerSource.SourcedContainer("probe",new ItemStack(Items.STICK),new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,"","",0,List.of("skill_tree_rpgs:paladin_tier_3_passive_2"))))));owner.spellModifierCache().clear();((SpellCaster.Player)p).getCooldownManager().reset(null);
  p.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:haste")).orElseThrow()).setBaseValue(100);var e=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);var source=p.damageSources().mobAttack(e);
  check(h.value().cost.cooldown.duration==80&&h.value().cost.cooldown.haste_affected,"80s base haste-aware passive metadata");check(FinalPurelight.rescue(true,p,source)&&!FinalPurelight.active(p),"Earlier lifesaver does not start cooldown or Purelight");
  check(FinalPurelight.rescue(false,p,source),"Fatal rescue starts while ready");check(p.getHealth()==100,"Full heal remains");long until=p.getPersistentData().getLongOr("final_purelight_cooldown_until",0);check(until-w.getGameTime()==1600,"Authoritative cooldown80s");check(((SpellCaster.Player)p).getCooldownManager().getCooldownDuration(h)==1600,"Native UI cooldown80s");
  FinalPurelight.stop(p);check(!FinalPurelight.rescue(false,p,source),"Downing/ending does not bypass cooldown");var fresh=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"CooldownClone"));FinalPurelight.copyCooldown(p,fresh);check(fresh.getPersistentData().getLongOr("final_purelight_cooldown_until",0)==until,"Cooldown survives recreation/death clone");check(((SpellCaster.Player)fresh).getCooldownManager().getCooldownDuration(h)==1600,"Recreated native cooldown preserved");
  var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,p.registryAccess());p.saveWithoutId(saved);fresh.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,p.registryAccess(),saved.buildResult()));check(fresh.getPersistentData().getLongOr("final_purelight_cooldown_until",0)==until,"Cooldown survives native player save/load");
  p.getPersistentData().putLong("final_purelight_cooldown_until",w.getGameTime());p.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:haste")).orElseThrow()).setBaseValue(200);check(FinalPurelight.rescue(false,p,source),"Expired cooldown allows new rescue");check(p.getPersistentData().getLongOr("final_purelight_cooldown_until",0)-w.getGameTime()==800,"200% haste gives40s");
  p.getAttribute(Attributes.MAX_ABSORPTION).setBaseValue(20);p.setAbsorptionAmount(10);p.setHealth(50);p.getPersistentData().putLong("final_purelight_next",0);NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));check(p.getHealth()==49&&p.getAbsorptionAmount()==10,"Existing absorption-bypassing drain retained");FinalPurelight.stop(p);check(!p.hasEffect(FinalRules.effect("purelight_cost")),"End clears synchronized visual driver");
 }catch(Throwable t){t.printStackTrace();check(false,"Exception "+t);}finally{try{Files.write(Path.of("phase-two-checks.txt"),lines);Files.writeString(Path.of("phase-two-result.txt"),(failed==0?"PASS ":"FAIL ")+lines.size()+" checks; failures="+failed+"\n");}catch(Exception ignored){}event.getServer().halt(false);}}
}
